rmSync(process.env.TMPDIR + '/jt/data2', { recursive: true, force: true });
const env = { ...process.env, PORT: String(PORT), DATABASE_PATH: DB };
const base = `http://127.0.0.1:${PORT}`;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const procs = {};
const start = (n) => (procs[n] = spawn('node', ['--disable-warning=ExperimentalWarning', `${ROOT}/dist/${n}.js`], { env, stdio: 'ignore' }));
let fails = 0; const check = (c, m) => { console.log((c ? 'PASS ' : 'FAIL ') + m); if (!c) fails++; };
const post = (body, raw) => fetch(base + '/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body) }).then(async (r) => ({ s: r.status, j: await r.json() }));
const get = (id) => fetch(base + '/api/jobs/' + id).then((r) => r.json());
async function waitFor(id, pred, ms = 15000) { const e = Date.now() + ms; let j; while (Date.now() < e) { j = await get(id); if (pred(j)) return j; await sleep(100); } return j; }
start('server'); start('worker'); await sleep(1500);

const weird = 'a\u0000b\ud800c';
