check(r.s === 201 && r.j.input === weird, 'NUL/surrogate input stored exactly: ' + JSON.stringify(r.j.input));
const w = await waitFor(r.j.id, (j) => j.status === 'completed');
check(w.result && w.result.output === weird.toUpperCase(), 'NUL/surrogate output exact: ' + JSON.stringify(w.result));

r = await post(null, ' '.repeat(17000) + '{"input":"hello"}');
check(r.s === 201 && r.j.input === 'hello', 'large whitespace body accepted: ' + r.s);

// Recovery budget: failAttempts 0, kill during each attempt so attempts reaches 3 without completing.
// Use steps 20 so the worker is always mid-job when killed.
r = await post({ input: 'budget', steps: 20, failAttempts: 0 });
const id = r.j.id;
for (let k = 1; k <= 3; k++) {
  await waitFor(id, (j) => j.status === 'running' && j.progress.completed >= 1, 5000);
  procs.worker.kill('SIGKILL'); await sleep(300);
  const before = await get(id);
  start('worker'); await sleep(400);
  if (k < 3) {
    const after = await waitFor(id, (j) => j.status === 'running' || j.status === 'queued', 3000);
    check(after.attempts === before.attempts + 1 || after.attempts === k + 1, `attempt numbering after kill ${k}: attempts ${after.attempts}`);
  }
}
const fin = await waitFor(id, (j) => j.status === 'completed' || j.status === 'failed', 15000);
check(fin.attempts <= 3, `attempts never exceed 3: ${fin.attempts}`);
console.log('final:', fin.status, fin.attempts, fin.error);
for (const p of Object.values(procs)) p.kill('SIGTERM');
await sleep(300);
console.log(fails ? `${fails} FAILED` : 'ALL PASSED');
process.exit(fails ? 1 : 0);
EOF
