}
let r = await call('POST', '/api/jobs', '{bad json', { 'content-type': 'application/json' });
check(r.status === 400 && r.json.error.fields[0].field === 'body', 'malformed json');
r = await call('POST', '/api/jobs', '{"input":"a"}', { 'content-type': 'text/plain' });
check(r.status === 400 && r.json.error.fields[0].field === 'body', 'text/plain');
r = await call('POST', '/api/jobs', { input: 'a' }, { 'idempotency-key': 'bad key!' });
check(r.status === 400 && r.json.error.fields.some((x) => x.field === 'Idempotency-Key'), 'bad idem key');
r = await call('POST', '/api/jobs', { input: 'hello ß', steps: 3 });
check(r.status === 201 && r.json.status === 'queued' && r.json.steps === 3 && r.json.progress.total === 3, 'create');
